class Häufigkeit {

   int[] zähler = new int[6];    // zähler[0] ist die Zahl der Einsen, zähler[1] die der Zweien, usw. 


   Häufigkeit() {
      int n = Input.readInt("Wie oft soll gewürfelt werden?");


      println("\nGewürfelte Zahlen: ");
      String ausgabe = ""; 
      for (int i = 0; i < n; i++) {
         int zahl;    // TODO1 zufällige Zahl aus {1; 2; ...; 6}
         zähler[0];   // TODO2 zählerArray an der richtigen Stelle um eins erhöhen

         ausgabe += zahl; 
         if(i < n - 1) {
            ausgabe += ", ";
         }
      }
      println(ausgabe);


      // Häufigkeitsausgaben
      println("\nAbsolute Häufigkeiten: ");
      for (int i = 0; i < 6; i++) {
         print((i + 1) + ": ");
         println(zähler[i], Color.goldenrod);
      }

      println("\nRelative Häufigkeiten: ");
      for (int i = 0; i < 6; i++) {
         print((i + 1) + ": ");
         println((double)zähler[i] / n, Color.cadetblue);
      }
   }
}
